package dev.aerove.lite.data

import dev.aerove.lite.profilebuilder.BuilderEntry
import dev.aerove.lite.profilebuilder.DefaultGlobalProxyLinkCodec
import kotlinx.coroutines.Job
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withContext
import org.junit.Assert.*
import org.junit.Test

class ProfileLinkEncoderTest {
    @Test fun matchesStandardGoOracleIncludingAllTwelveProtocolsAndTransports() = runBlocking {
        // Expected bytes came from the unmodified encode functions in Standard core/share_link.go.
        val fixture = ConfigYaml.parse(ORACLE)
        @Suppress("UNCHECKED_CAST")
        val nodes = fixture["nodes"] as List<Map<String, Any?>>
        val expected = fixture["links"] as List<*>
        val actual = ProfileLinkEncoder().encode(nodes)
        assertEquals(expected.size, actual.size)
        expected.forEachIndexed { index, link -> assertEquals("Oracle node $index", link, actual[index]) }
    }

    @Test fun unsupportedMappingsRetainTheirSlots() = runBlocking {
        val nodes = listOf(mapOf("type" to "unknown", "server" to "a"), mapOf("type" to "ss"),
            mapOf("type" to "ssr", "server" to "::1"),
            mapOf("type" to "ss", "server" to "a", "plugin" to "unknown"),
            mapOf("type" to "hysteria2", "server" to "a", "realm-opts" to mapOf("enable" to true)))
        assertEquals(List(nodes.size) { "" }, ProfileLinkEncoder().encode(nodes))
    }

    @Test fun supportedNodesRoundTripThroughTheRealLiteDecoder() = runBlocking {
        val uuid = "b831381d-6324-4d53-ad4f-8cda48b30811"
        val password = "中文 :@/?&+😀"
        val nodes = listOf(
            mapOf("type" to "ss", "cipher" to "aes-128-gcm", "password" to password),
            mapOf("type" to "trojan", "password" to password),
            mapOf("type" to "vmess", "uuid" to uuid, "cipher" to "auto", "network" to "ws", "ws-opts" to mapOf("path" to "/a?b=1")),
            mapOf("type" to "vless", "uuid" to uuid),
            mapOf("type" to "hysteria2", "password" to password),
            mapOf("type" to "tuic", "uuid" to uuid, "password" to password),
            mapOf("type" to "socks5", "username" to "user", "password" to password),
            mapOf("type" to "anytls", "password" to password),
        ).mapIndexed { i, fields -> fields + mapOf("name" to "节点 $i 😀", "server" to "2001:db8::1", "port" to 443) }
        val links = ProfileLinkEncoder().encode(nodes)
        links.forEachIndexed { index, link ->
            val batch = ProfileLinkDecoder().decode(link)
            assertTrue("$index: ${batch.errors}", batch.errors.isEmpty())
            val config = ConfigYaml.parse((batch.entries.single() as ProfileLinkEntry.Inline).config)
            val proxy = (config["proxies"] as List<*>).single() as Map<*, *>
            listOf("type", "name", "server", "password", "uuid").forEach { key ->
                if (nodes[index].containsKey(key)) assertEquals("$index.$key", nodes[index][key], proxy[key])
            }
        }
    }

    @Test fun adapterRequiresNativeValidationAndKeepsDecoderErrors() = runBlocking {
        var calls = 0
        val codec = DefaultGlobalProxyLinkCodec(validator = { yaml ->
            calls++
            assertTrue(ConfigYaml.parse(yaml).containsKey("proxies"))
            null
        })
        val entry = BuilderEntry("节点", mapOf("type" to "ss", "server" to "a.example", "port" to 443,
            "cipher" to "aes-128-gcm", "password" to "p"))
        codec.validate(listOf(entry))
        val links = codec.encode(listOf(entry))
        assertEquals("节点", codec.decode(links.single()).single().name)
        assertEquals(2, calls)
        val rejected = runCatching { codec.decode(links.single() + "\nssr://invalid") }.exceptionOrNull()
        assertTrue(rejected is IllegalArgumentException)
        assertTrue(rejected!!.message!!.contains("$.scheme"))
        assertEquals(2, calls)
        val diagnostic = DefaultGlobalProxyLinkCodec(validator = { "proxies[0].cipher: rejected by core" })
        assertEquals("proxies[0].cipher: rejected by core", runCatching { diagnostic.validate(listOf(entry)) }.exceptionOrNull()?.message)
        assertTrue(runCatching { codec.decode("https://subscription.example/a") }.isFailure)
    }

    @Test fun boundsMalformedUnicodeRecursionAndCancellation() = runBlocking {
        val limits = ProfileLinkLimits(maxLinks = 1)
        assertTrue(runCatching { ProfileLinkEncoder(limits).encode(listOf(emptyMap(), emptyMap())) }.isFailure)
        assertTrue(runCatching { ProfileLinkEncoder().encode(listOf(mapOf("name" to "\uD800"))) }.isFailure)
        val cycle = mutableMapOf<String, Any?>()
        cycle["self"] = cycle
        assertTrue(runCatching { ProfileLinkEncoder().encode(listOf(cycle)) }.isFailure)
        val job = Job().apply { cancel() }
        assertTrue(runCatching { withContext(job) { ProfileLinkEncoder().encode(emptyList()) } }.exceptionOrNull() is CancellationException)
    }

